async function addFiles(files){if(state.loading||state.exporting)return;const all=Array.from(files);if(!all.length)return;state.loading=true;updateControls();toast(t('loading'));const maxPixels=40000000/Math.min(24,state.photos.length+all.length);for(const p of state.photos){if(p.image.width*p.image.height>maxPixels){const s=Math.sqrt(maxPixels/(p.image.width*p.image.height)),small=document.createElement('canvas');small.width=Math.max(1,Math.floor(p.image.width*s));small.height=Math.max(1,Math.floor(p.image.height*s));small.getContext('2d').drawImage(p.image,0,0,small.width,small.height);p.image.width=1;p.image.height=1;p.image=small;}}let added=0,failed=0,limited=false;for(const file of all){if(state.photos.length>=24){limited=true;break;}try{state.photos.push(await decode(file,maxPixels));added++;}catch{failed++;}}state.loading=false;if(added){state.selected=state.photos.length-added;resetPositions();}renderPhotos();renderLayouts();updateControls();draw();toast([added?`${t('added')} ${added} ${t('photoUnit')}.`:'',failed?t('invalid'):'',limited?t('limit'):''].filter(Boolean).join(' '));$('file-input').value='';}
